using InterCat.Desktop.Theme;

// Writes the theme definition and its measured verification into theme/ (section 21.2 item 11). Goldens are
// regenerated by this explicit command, never as a side effect of running tests (section 13.6); a test holds the
// committed files to exactly what this writes (ADR-050).
string outputDirectory = args.Length > 0 ? args[0] : "theme";
Directory.CreateDirectory(outputDirectory);

ThemeReport report = ThemeVerification.Verify(DateTimeOffset.UtcNow);

await File.WriteAllTextAsync(Path.Combine(outputDirectory, "tokens.json"), ThemeFiles.Tokens()).ConfigureAwait(false);
await File.WriteAllTextAsync(Path.Combine(outputDirectory, "contrast-report.json"), ThemeFiles.Report(report)).ConfigureAwait(false);
await File.WriteAllTextAsync(Path.Combine(outputDirectory, "README.md"), ThemeFiles.Summary(report)).ConfigureAwait(false);

Console.WriteLine(report.Satisfied
    ? $"Theme {report.ThemeVersion} satisfies every recorded threshold."
    : $"Theme {report.ThemeVersion} FAILS at least one threshold; see contrast-report.json.");
return report.Satisfied ? 0 : 1;
